sys_script.script:
(function executeRule(current, previous) {

    try {

        var number =
            current.getValue('number') || 'Attendance';

        // ---------------------------------------------
        // Attendance Date
        // 2026-10-12 -> 12-Oct-2026
        // ---------------------------------------------
        var attendanceDate =
            current.getValue('attendance_date') || '';

        var formattedDate = '-';

        if (attendanceDate) {

            var dateParts =
                attendanceDate.split('-');

            if (dateParts.length === 3) {

                var months = [
                    'Jan', 'Feb', 'Mar', 'Apr',
                    'May', 'Jun', 'Jul', 'Aug',
                    'Sep', 'Oct', 'Nov', 'Dec'
                ];

                var monthIndex =
                    parseInt(dateParts[1], 10) - 1;

                if (
                    monthIndex >= 0 &&
                    monthIndex <= 11
                ) {

                    formattedDate =
                        dateParts[2] +
                        '-' +
                        months[monthIndex] +
                        '-' +
                        dateParts[0];

                }
            }
        }


        // ---------------------------------------------
        // Check-In converted to IST
        // ---------------------------------------------
        var formattedTime = '-';

        var checkIn =
            current.getValue('check_in');

        if (checkIn) {

            var indiaDateTime =
                new GlideDateTime(checkIn);

            indiaDateTime.addSeconds(19800);

            var indiaValue =
                indiaDateTime.getValue();


            var hour =
                parseInt(
                    indiaValue.substring(11, 13),
                    10
                );

            var minute =
                indiaValue.substring(14, 16);


            var suffix =
                hour >= 12
                    ? 'PM'
                    : 'AM';


            hour =
                hour % 12;

            if (hour === 0) {
                hour = 12;
            }


            formattedTime =
                hour +
                ':' +
                minute +
                ' ' +
                suffix;

        }


        // ---------------------------------------------
        // Status display value
        // ---------------------------------------------
        var status =
            current.getDisplayValue('status');

        if (!status) {

            status =
                current.getValue('status') || '-';

        }


        // ---------------------------------------------
        // Final label
        // ---------------------------------------------
        var referenceLabel =
            number +
            ' • ' +
            formattedDate +
            ' • ' +
            formattedTime +
            ' • ' +
            status;


        current.setValue(
            'reference_label',
            referenceLabel
        );

    }
    catch (e) {

        gs.error(
            '[SmartAttend Reference Label] ' +
            e.message
        );

    }

})(current, previous);
